content:
130
   131      return sz;
   132
   133   block_err:
   134      cram_free_block(b);
   135      return -1;
   136  }
   137
   138  /*
   139   * Decodes a CRAM block compression header.
   140   * Returns header ptr on success
   141   *         NULL on failure
   142   */
   143  cram_block_compression_hdr *cram_decode_compression_header(cram_fd *fd,
   144                                                             cram_block *b) {
   145      char *cp, *endp, *cp_copy;
   146      cram_block_compression_hdr *hdr = calloc(1, sizeof(*hdr));
   147      int i, err = 0;
   148      int32_t map_size = 0, map_count = 0;
   149
   150      if (!hdr)
   151          return NULL;
   152
   153      if (b->method != RAW) {
   154          if (cram_uncompress_block(b)) {
   155              free(hdr);
   156              return NULL;
   157          }
   158      }
   159
   160      cp = (char *)b->data;
   161      endp = cp + b->uncomp_size;
   162
   163      if (CRAM_MAJOR_VERS(fd->version) == 1) {
   164          hdr->ref_seq_id = fd->vv.varint_get32(&cp, endp, &err);
   165          if (CRAM_MAJOR_VERS(fd->version) >= 4) {
   166              hdr->ref_seq_start = fd->vv.varint_get64(&cp, endp, &err);
   167              hdr->ref_seq_span  = fd->vv.varint_get64(&cp, endp, &err);
   168          } else {
   169              hdr->ref_seq_start = fd->vv.varint_get32(&cp, endp, &err);
   170              hdr->ref_seq_span  = fd->vv.varint_get32(&cp, endp, &err);
   171          }
   172          hdr->num_records   = fd->vv.varint_get32(&cp, endp, &err);
   173          hdr->num_landmarks = fd->vv.varint_get32(&cp, endp, &err);
   174          if (hdr->num_landmarks < 0 ||
   175              hdr->num_landmarks >= SIZE_MAX / sizeof(int32_t) ||
   176              endp - cp < hdr->num_landmarks) {
   177              free(hdr);
   178              return NULL;
   179          }
   180          if (!(hdr->landmark = malloc(hdr->num_landmarks * sizeof(int32_t)))) {
   181              free(hdr);
   182              return NULL;
   183          }
   184          for (i = 0; i < hdr->num_landmarks; i++)
   185              hdr->landmark[i] = fd->vv.varint_get32(&cp, endp, &err);;
   186      }
   187
   188      hdr->preservation_map = kh_init(map);
   189
   190      memset(hdr->rec_encoding_map, 0,
   191             CRAM_MAP_HASH * sizeof(hdr->rec_encoding_map[0]));
   192      memset(hdr->tag_encoding_map, 0,
   193             CRAM_MAP_HASH * sizeof(hdr->tag_encoding_map[0]));
   194
   195      if (!hdr->preservation_map) {
   196          cram_free_compression_header(hdr);
   197          return NULL;
   198      }
   199
   200      /* Initialise defaults for preservation map */
   201      hdr->read_names_included = 0;
   202      hdr->AP_delta = 1;
   203      hdr->qs_seq_orient = 1;
   204      memcpy(hdr->substitution_matrix, "CGTNAGTNACTNACGNACGT", 20);
   205
   206      /* Preservation map */
   207      map_size  = fd->vv.varint_get32(&cp, endp, &err); cp_copy = cp;
   208      map_count = fd->vv.varint_get32(&cp, endp, &err);
   209      for (i = 0; i < map_count; i++) {
   210          pmap_t hd;
   211          khint_t k;
   212          int r;
   213
   214          if (endp - cp < 3) {
   215              cram_free_compression_header(hdr);
   216              return NULL;
   217          }
   218          cp += 2;
   219          switch(CRAM_KEY(cp[-2],cp[-1])) {
   220          case CRAM_KEY('M','I'): // was mapped QS included in V1.0
   221          case CRAM_KEY('U','I'): // was unmapped QS included in V1.0
   222          case CRAM_KEY('P','I'): // was unmapped placed in V1.0
   223              hd.i = *cp++;
   224              break;
   225
   226          case CRAM_KEY('R','N'):
   227              hd.i = *cp++;
   228              k = kh_put(map, hdr->preservation_map, "RN", &r);
   229              if (-1 == r) {
   230                  cram_free_compression_header(hdr);
   231                  return NULL;
   232              }
   233
   234              kh_val(hdr->preservation_map, k) = hd;
   235              hdr->read_names_included = hd.i;
   236              break;
   237
   238          case CRAM_KEY('A','P'):
   239              hd.i = *cp++;
   240              k = kh_put(map, hdr->preservation_map, "AP", &r);
   241              if (-1 == r) {
   242                  cram_free_compression_header(hdr);
   243                  return NULL;
   244              }
   245
   246              kh_val(hdr->preservation_map, k) = hd;
   247              hdr->AP_delta = hd.i;
   248              break;
   249
   250          case CRAM_KEY('R','R'):
   251              hd.i = *cp++;
   252              k = kh_put(map, hdr->preservation_map, "RR", &r);
   253              if (-1 == r) {
   254                  cram_free_compression_header(hdr);
   255                  return NULL;
   256              }
   257
   258              kh_val(hdr->preservation_map, k) = hd;
   259              hdr->no_ref = !hd.i;
   260              break;
   261
   262          case CRAM_KEY('Q','O'):
   263              hd.i = *cp++;
   264              k = kh_put(map, hdr->preservation_map, "QO", &r);
   265              if (-1 == r) {
   266                  cram_free_compression_header(hdr);
   267                  return NULL;
   268              }
   269
   270              kh_val(hdr->preservation_map, k) = hd;
   271              hdr->qs_seq_orient = hd.i;
   272              break;
   273
   274          case CRAM_KEY('S','M'):
   275              if (endp - cp < 5) {
   276                  cram_free_compression_header(hdr);
   277                  return NULL;
   278              }
   279              hdr->substitution_matrix[0][(cp[0]>>6)&3] = 'C';
   280              hdr->substitution_matrix[0][(cp[0]>>4)&3] = 'G';
   281              hdr->substitution_matrix[0][(cp[0]>>2)&3] = 'T';
   282              hdr->substitution_matrix[0][(cp[0]>>0)&3] = 'N';
   283
   284              hdr->substitution_matrix[1][(cp[1]>>6)&3] = 'A';
   285              hdr->substitution_matrix[1][(cp[1]>>4)&3] = 'G';
   286              hdr->substitution_matrix[1][(cp[1]>>2)&3] = 'T';
   287              hdr->substitution_matrix[1][(cp[1]>>0)&3] = 'N';
   288
   289              hdr->substitution_matrix[2][(cp[2]>>6)&3] = 'A';
   290              hdr->substitution_matrix[2][(cp[2]>>4)&3] = 'C';
   291              hdr->substitution_matrix[2][(cp[2]>>2)&3] = 'T';
   292              hdr->substitution_matrix[2][(cp[2]>>0)&3] = 'N';
   293
   294              hdr->substitution_matrix[3][(cp[3]>>6)&3] = 'A';
   295              hdr->substitution_matrix[3][(cp[3]>>4)&3] = 'C';
   296              hdr->substitution_matrix[3][(cp[3]>>2)&3] = 'G';
   297              hdr->substitution_matrix[3][(cp[3]>>0)&3] = 'N';
   298
   299              hdr->substitution_matrix[4][(cp[4]>>6)&3] = 'A';
   300              hdr->substitution_matrix[4][(cp[4]>>4)&3] = 'C';
   301              hdr->substitution_matrix[4][(cp[4]>>2)&3] = 'G';
   302              hdr->substitution_matrix[4][(cp[4]>>0)&3] = 'T';
   303
   304              hd.p = cp;
   305              cp += 5;
   306
   307              k = kh_put(map, hdr->preservation_map, "SM", &r);
   308              if (-1 == r) {
   309                  cram_free_compression_header(hdr);
   310                  return NULL;
   311              }
   312              kh_val(hdr->preservation_map, k) = hd;
   313              break;
   314
   315          case CRAM_KEY('T','D'): {
   316              int sz = cram_decode_TD(fd, cp, endp, hdr); // tag dictionary
   317              if (sz < 0) {
   318                  cram_free_compression_header(hdr);
   319                  return NULL;
   320              }
   321
   322              hd.p = cp;
   323              cp += sz;
   324
   325              k = kh_put(map, hdr->preservation_map, "TD", &r);
   326              if (-1 == r) {
   327                  cram_free_compression_header(hdr);
   328                  return NULL;
   329              }
   330              kh_val(hdr->preservation_map, k) = hd;
   331              break;
   332          }
   333
   334          default:
   335              hts_log_warning("Unrecognised preservation map key %c%c", cp[-2], cp[-1]);
   336              // guess byte;
   337              cp++;
   338              break;
   339          }
   340      }
   341      if (cp - cp_copy != map_size) {
   342          cram_free_compression_header(hdr);
   343          return NULL;
   344      }
   345
   346      /* Record encoding map */
   347      map_size  = fd->vv.varint_get32(&cp, endp, &err); cp_copy = cp;
   348      map_count = fd->vv.varint_get32(&cp, endp, &err);
   349      int is_v4 = CRAM_MAJOR_VERS(fd->version) >= 4 ? 1 : 0;
   350      for (i = 0; i < map_count; i++) {
   351          char *key = cp;
   352          int32_t encoding = E_NULL;
   353          int32_t size = 0;
   354          ptrdiff_t offset;
   355          cram_map *m;
   356          enum cram_DS_ID ds_id;
   357          enum cram_external_type type;
   358
   359          if (endp - cp < 4) {
   360              cram_free_compression_header(hdr);
   361              return NULL;
   362          }
   363
   364          cp += 2;
   365          encoding = fd->vv.varint_get32(&cp, endp, &err);
   366          size     = fd->vv.varint_get32(&cp, endp, &err);
   367
   368          offset = cp - (char *)b->data;
   369
   370          if (encoding == E_NULL)
   371              continue;
   372
   373          if (size < 0 || endp - cp < size) {
   374              cram_free_compression_header(hdr);
   375              return NULL;
   376          }
   377
   378          //printf("%s codes for %.2s\n", cram_encoding2str(encoding), key);
   379
   380          /*
   381           * For CRAM1.0 CF and BF are Byte and not Int.
   382           * Practically speaking it makes no difference unless we have a
   383           * 1.0 format file that stores these in EXTERNAL as only then
   384           * does Byte vs Int matter.
   385           *
   386           * Neither this C code nor Java reference implementations did this,
   387           * so we gloss over it and treat them as int.
   388           */
   389          ds_id = DS_CORE;
   390          if (key[0] == 'B' && key[1] == 'F') {
   391              ds_id = DS_BF; type = E_INT;
   392          } else if (key[0] == 'C' && key[1] == 'F') {
   393              ds_id = DS_CF; type = E_INT;
   394          } else if (key[0] == 'R' && key[1] == 'I') {
   395              ds_id = DS_RI; type = E_INT;
   396          } else if (key[0] == 'R' && key[1] == 'L') {
   397              ds_id = DS_RL; type = E_INT;
   398          } else if (key[0] == 'A' && key[1] == 'P') {
   399              ds_id = DS_AP;
   400              type = is_v4 ? E_SLONG : E_INT;
   401          } else if (key[0] == 'R' && key[1] == 'G') {
   402              ds_id = DS_RG;
   403              type = E_INT;
   404          } else if (key[0] == 'M' && key[1] == 'F') {
   405              ds_id = DS_MF; type = E_INT;
   406          } else if (key[0] == 'N' && key[1] == 'S') {
   407              ds_id = DS_NS; type = E_INT;
   408          } else if (key[0] == 'N' && key[1] == 'P') {
   409              ds_id = DS_NP;
   410              type = is_v4 ? E_LONG : E_INT;
   411          } else if (key[0] == 'T' && key[1] == 'S') {
   412              ds_id = DS_TS;
   413              type = is_v4 ? E_SLONG : E_INT;
   414          } else if (key[0] == 'N' && key[1] == 'F') {
   415              ds_id = DS_NF; type = E_INT;
   416          } else if (key[0] == 'T' && key[1] == 'C') {
   417              ds_id = DS_TC; type = E_BYTE;
   418          } else if (key[0] == 'T' && key[1] == 'N') {
   419              ds_id = DS_TN; type = E_INT;
   420          } else if (key[0] == 'F' && key[1] == 'N') {
   421              ds_id = DS_FN; type = E_INT;
   422          } else if (key[0] == 'F' && key[1] == 'C') {
   423              ds_id = DS_FC; type = E_BYTE;
   424          } else if (key[0] == 'F' && key[1] == 'P') {
   425              ds_id = DS_FP; type = E_INT;
   426          } else if (key[0] == 'B' && key[1] == 'S') {
   427              ds_id = DS_BS; type = E_BYTE;
   428          } else if (key[0] == 'I' && key[1] == 'N') {
   429              ds_id = DS_IN; type = E_BYTE_ARRAY;
   430          } else if (key[0] == 'S' && key[1] == 'C') {
   431              ds_id = DS_SC; type = E_BYTE_ARRAY;
   432          } else if (key[0] == 'D' && key[1] == 'L') {
   433              ds_id = DS_DL; type = E_INT;
   434          } else if (key[0] == 'B' && key[1] == 'A') {
   435              ds_id = DS_BA; type = E_BYTE;
   436          } else if (key[0] == 'B' && key[1] == 'B') {
   437              ds_id = DS_BB; type = E_BYTE_ARRAY;
   438          } else if (key[0] == 'R' && key[1] == 'S') {
   439              ds_id = DS_RS; type = E_INT;
   440          } else if (key[0] == 'P' && key[1] == 'D') {
   441              ds_id = DS_PD; type = E_INT;
   442          } else if (key[0] == 'H' && key[1] == 'C') {
   443              ds_id = DS_HC; type = E_INT;
   444          } else if (key[0] == 'M' && key[1] == 'Q') {
   445              ds_id = DS_MQ; type = E_INT;
   446          } else if (key[0] == 'R' && key[1] == 'N') {
   447              ds_id = DS_RN; type = E_BYTE_ARRAY_BLOCK;
   448          } else if (key[0] == 'Q' && key[1] == 'S') {
   449              ds_id = DS_QS; type = E_BYTE;
   450          } else if (key[0] == 'Q' && key[1] == 'Q') {
   451              ds_id = DS_QQ; type = E_BYTE_ARRAY;
   452          } else if (key[0] == 'T' && key[1] == 'L') {
   453              ds_id = DS_TL; type = E_INT;
   454          } else if (key[0] == 'T' && key[1] == 'M') {
   455          } else if (key[0] == 'T' && key[1] == 'V') {
   456          } else {
   457              hts_log_warning("Unrecognised key: %.2s", key);
   458          }
   459
   460          if (ds_id != DS_CORE) {
   461              if (hdr->codecs[ds_id] != NULL) {
   462                  hts_log_warning("Codec for key %.2s defined more than once",
   463                                  key);
   464                  hdr->codecs[ds_id]->free(hdr->codecs[ds_id]);
   465              }
   466              hdr->codecs[ds_id] = cram_decoder_init(hdr, encoding, cp, size,
   467                                                     type, fd->version, &fd->vv);
   468              if (!hdr->codecs[ds_id]) {
   469                  cram_free_compression_header(hdr);
   470                  return NULL;
   471              }
   472          }
   473
   474          cp += size;
   475
   476          // Fill out cram_map purely for cram_dump to dump out.
   477          m = malloc(sizeof(*m));
   478          if (!m) {
   479              cram_free_compression_header(hdr);
   480              return NULL;
   481          }
   482          m->key = CRAM_KEY(key[0], key[1]);
   483          m->encoding = encoding;
   484          m->size     = size;
   485          m->offset   = offset;
   486          m->codec = NULL;
   487
   488          m->next = hdr->rec_encoding_map[CRAM_MAP(key[0], key[1])];
   489          hdr->rec_encoding_map[CRAM_MAP(key[0], key[1])] = m;
   490      }
   491      if (cp - cp_copy != map_size) {
   492          cram_free_compression_header(hdr);
   493          return NULL;
   494      }
   495
   496      /* Tag encoding map */
   497      map_size  = fd->vv.varint_get32(&cp, endp, &err); cp_copy = cp;
   498      map_count = fd->vv.varint_get32(&cp, endp, &err);
   499      for (i = 0; i < map_count; i++) {
   500          int32_t encoding = E_NULL;
   501          int32_t size = 0;
   502          cram_map *m = malloc(sizeof(*m)); // FIXME: use pooled_alloc
   503          uint8_t key[3];
   504
   505          if (!m || endp - cp < 6) {
   506              free(m);
   507              cram_free_compression_header(hdr);
   508              return NULL;
   509          }
   510
   511          m->key = fd->vv.varint_get32(&cp, endp, &err);
   512          key[0] = m->key>>16;
   513          key[1] = m->key>>8;
   514          key[2] = m->key;
   515          encoding = fd->vv.varint_get32(&cp, endp, &err);
   516          size     = fd->vv.varint_get32(&cp, endp, &err);
   517
   518          m->encoding = encoding;
   519          m->size     = size;
   520          m->offset   = cp - (char *)b->data;
   521          if (size < 0 || endp - cp < size ||
   522              !(m->codec = cram_decoder_init(hdr, encoding, cp, size,
   523                                             E_BYTE_ARRAY_BLOCK, fd->version, &fd->vv))) {
   524              cram_free_compression_header(hdr);
   525              free(m);
   526              return NULL;
   527          }
   528
   529          cp += size;
   530
   531          m->next = hdr->tag_encoding_map[CRAM_MAP(key[0],key[1])];
   532          hdr->tag_encoding_map[CRAM_MAP(key[0],key[1])] = m;
   533      }
   534      if (err || cp - cp_copy != map_size) {
   535          cram_free_compression_header(hdr);
   536          return NULL;
   537      }
   538
   539      return hdr;
   540  }
